SINA_SMART["physio-renal-reabs"] = {"lecture":"physio-renal-reabs","title":"Renal physiology 5: tubular reabsorption","mapStatus":"auto: generated by universal.py from the lecture summary and key points; not human-reviewed","los":[{"id":"physio-renal-reabs:s0","text":"Describe and explain: The big picture","topic":"The big picture","sec":0,"importance":"standard","highYield":"untested"},{"id":"physio-renal-reabs:e0","text":"Cortical nephrons 85% (short loops, peritubular capillaries); juxtamedullary 15% (long loops, vasa recta, concentrate urine).","topic":"Two types of nephrons","sec":1,"importance":"core","highYield":"untested"},{"id":"physio-renal-reabs:e1","text":"Transcellular and paracellular (leaky junctions) routes; peritubular capillaries take up the fluid.","topic":"Routes and transport","sec":2,"importance":"core","highYield":"untested"},{"id":"physio-renal-reabs:e2","text":"Basal Na+–K+ pump = primary active; apical symports = secondary active.","topic":"Routes and transport","sec":2,"importance":"core","highYield":"untested"},{"id":"physio-renal-reabs:e3","text":"Glucose: SGLT with Na+; normally all reabsorbed.","topic":"Routes and transport","sec":2,"importance":"core","highYield":"untested"},{"id":"physio-renal-reabs:e4","text":"PCT: 65% of filtrate; microvilli, mitochondria; 6% of resting ATP; fluid leaves isosmotic.","topic":"The proximal convoluted tubule","sec":3,"importance":"core","highYield":"untested"},{"id":"physio-renal-reabs:e5","text":"Descending limb: 20% more water, unregulated. Final 15%: hormonal.","topic":"The proximal convoluted tubule","sec":3,"importance":"core","highYield":"untested"},{"id":"physio-renal-reabs:e6","text":"Descending limb permeable to water only; ascending limb to solutes only.","topic":"Countercurrent multiplier","sec":4,"importance":"core","highYield":"untested"},{"id":"physio-renal-reabs:e7","text":"Countercurrent multiplier builds 300 → about 1 200-1 400 mOsm.","topic":"Countercurrent multiplier","sec":4,"importance":"core","highYield":"untested"}],"vmap":{},"mlevel":{"k1fgnk":"a","pvcd0w":"a","3vvqf6":"a","h3xdmu":"a","15hhmoa":"a","66r5d0":"a","1oqf9fr":"a","1s06fm5":"a","12ntqel":"a","1mm6t13":"a","lkld0s":"a","1o17w7z":"a","1niqao3":"a","1ny1szc":"a","bbtx5b":"a","1uu5bx3":"a","1tmp6l4":"a","hh3qiv":"a"},"mapCounts":{"verified":0,"auto":18,"ambiguous":0,"missing":0},"mrules":[],"items":[],"experimental":[],"status":{},"difficulty":{},"expl":{"physio-renal-reabs:s0":{"s":0,"u":["Tubular reabsorption reclaims water and solutes from tubular fluid and returns them to the blood.","The proximal tubule takes back about 65% ; the descending limb about 20% more; the last 15% is hormone-controlled."],"dp":[]},"physio-renal-reabs:e0":{"s":1,"u":["Cortical nephrons 85% (short loops, peritubular capillaries); juxtamedullary 15% (long loops, vasa recta, concentrate urine).","Efferent arteriole: Cortical = Branches into peritubular capillaries around PCT and DCT; Juxtamedullary = Branches into vasa recta around the long loop.","Loop: Cortical = Short; Juxtamedullary = Very long ; maintain the medullary salinity gradient and conserve water."],"dp":[]},"physio-renal-reabs:e1":{"s":2,"u":["Transcellular and paracellular (leaky junctions) routes; peritubular capillaries take up the fluid.","Paracellular route: between PCT cells; junctions are leaky and let much water through.","Reabsorbed fluid is taken up by the peritubular capillaries ."],"dp":[]},"physio-renal-reabs:e2":{"s":2,"u":["Basal Na+–K+ pump = primary active; apical symports = secondary active.","Symports on the apical surface: secondary active transport , no direct ATP but depend on the Na+ gradient set by the pumps.","Na+–K+ pumps on the basal surface keep Na+ from accumulating: primary active transport (use ATP)."],"dp":[]},"physio-renal-reabs:e3":{"s":2,"u":["Glucose: SGLT with Na+; normally all reabsorbed.","Glucose is co-transported with Na+ by SGLT proteins; normally all glucose is reabsorbed .","Reabsorbed fluid is taken up by the peritubular capillaries ."],"dp":[{"h":"SGLT2 inhibitors","t":"Drugs such as dapagliflozin block SGLT2 in the proximal tubule, so glucose escapes into the urine: a way to lower blood glucose in type 2 diabetes that also protects heart and kidney. Beyond the lecture."}]},"physio-renal-reabs:e4":{"s":3,"u":["PCT: 65% of filtrate; microvilli, mitochondria; 6% of resting ATP; fluid leaves isosmotic.","Prominent microvilli , great length, abundant mitochondria for active transport.","PCTs alone use about 6% of resting ATP and calorie consumption."],"dp":[]},"physio-renal-reabs:e5":{"s":3,"u":["Descending limb: 20% more water, unregulated. Final 15%: hormonal.","Another 20% of water is reabsorbed in the descending limb (continuous, unregulated ).","The final 15% is absorbed later under hormonal control ."],"dp":[]},"physio-renal-reabs:e6":{"s":4,"u":["Descending limb permeable to water only; ascending limb to solutes only.","Permeable to water , impermeable to solutes: Permeable to solutes (active Na+ transport, Cl− follows), impermeable to water.","Water cannot be pumped and will not cross if isotonic, so the loop builds a concentration gradient ; the ascending limb sets it up."],"dp":[]},"physio-renal-reabs:e7":{"s":4,"u":["Countercurrent multiplier builds 300 → about 1 200-1 400 mOsm.","Repeating cycles of pumping and fluid advancing multiply a small difference (300 → 400/200) into a gradient from 300 mOsm in the cortex to about 1 200 to 1 400 mOsm deep in the medulla. 'Countercurrent' = fluid flows in opposite directions in the two adjoining limbs.","The kidneys keep plasma osmolarity at 300 mOsm ."],"dp":[]}},"meta":{"k1fgnk":{"a":"recall","vg":"physio-renal-reabs:e0/recall/1"},"pvcd0w":{"a":"recall","vg":"physio-renal-reabs:e0/recall/1"},"3vvqf6":{"a":"recall","vg":"physio-renal-reabs:e0/recall/2"},"h3xdmu":{"a":"relationship","vg":"physio-renal-reabs:e1/relationship/1"},"15hhmoa":{"a":"recall","vg":"physio-renal-reabs:e2/recall/1"},"66r5d0":{"a":"recall","vg":"physio-renal-reabs:e2/recall/1"},"1oqf9fr":{"a":"recall","vg":"physio-renal-reabs:e3/recall/1"},"1s06fm5":{"a":"recall","vg":"physio-renal-reabs:e4/recall/1"},"12ntqel":{"a":"recall","vg":"physio-renal-reabs:e4/recall/2"},"1mm6t13":{"a":"recall","vg":"physio-renal-reabs:s0/recall/1"},"lkld0s":{"a":"recall","vg":"physio-renal-reabs:e5/recall/1"},"1o17w7z":{"a":"recall","vg":"physio-renal-reabs:e5/recall/2"},"1niqao3":{"a":"recall","vg":"physio-renal-reabs:e6/recall/1"},"1ny1szc":{"a":"recall","vg":"physio-renal-reabs:e6/recall/1"},"bbtx5b":{"a":"recall","vg":"physio-renal-reabs:e6/recall/2"},"1uu5bx3":{"a":"recall","vg":"physio-renal-reabs:e7/recall/1"},"1tmp6l4":{"a":"recall","vg":"physio-renal-reabs:e7/recall/2"},"hh3qiv":{"a":"recall","vg":"physio-renal-reabs:e1/recall/1"}},"explRev":"8ba54135668f"};
